ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  resourceLogs: [
    {
      resource: {
        attributes: [
          { key: "service.name", value: { stringValue: "mulesoft-fulfillment-api" } },
          { key: "service.version", value: { stringValue: "1.0.0-demo" } },
          { key: "service.namespace", value: { stringValue: "prism-demo" } },
          { key: "deployment.environment.name", value: { stringValue: p('prism.environment') } },
          { key: "prism.project.name", value: { stringValue: p('prism.project.name') } },
          { key: "prism.repository.url", value: { stringValue: p('prism.repository.url') } },
          { key: "prism.repository.branch", value: { stringValue: p('prism.repository.branch') } },
          { key: "mule.application.name", value: { stringValue: app.name } },
          { key: "mule.deployment.type", value: { stringValue: "standalone-demo" } }
        ]
      },
      scopeLogs: [
        {
          scope: { name: "prism.demo.mulesoft.fulfillment" },
          logRecords: [
            {
              severityNumber: 17,
              severityText: "ERROR",
              body: { stringValue: vars.originalErrorMessage },
              attributes: [
                { key: "exception.type", value: { stringValue: vars.originalErrorType } },
                { key: "exception.message", value: { stringValue: vars.originalErrorMessage } },
                { key: "exception.stacktrace", value: { stringValue: error.detailedDescription default vars.originalErrorMessage } },
                { key: "mule.flow.name", value: { stringValue: flow.name } },
                { key: "logger.name", value: { stringValue: "prism.demo.mulesoft.fulfillment" } },
                { key: "prism.demo.scenario", value: { stringValue: vars.scenario } },
                { key: "prism.demo.intentional", value: { stringValue: "true" } },
                { key: "order.id", value: { stringValue: vars.orderId } },
                { key: "http.route", value: { stringValue: "/fulfill/{orderId}" } },
                { key: "http.request.method", value: { stringValue: "POST" } }
              ]
            }
          ]
        }
      ]
    }
  ]
}
